    return list(map(int, input().split()))

def read_string():
    return input().strip()

def dfs(node, parent, graph, colors, win_map):
    win_map[node] = 'N'
    for neighbor in graph[node]:
        if neighbor != parent:
            dfs(neighbor, node, graph, colors, win_map)
            if win_map[neighbor] == 'N':
                win_map[node] = 'W'
                return
    if colors[node] == 'W':
